mapper.update:
update aps_plan set status = 'DISCARDED', discard_reason = #{reason}, row_ver = row_ver + 1,
                    updated_at = now(), updated_by = #{by}
 where plan_id = #{id} and status = 'CALCULATED' and row_ver = #{rowVer}

update aps_plan set status = 'APPLIED', applied_at = now(), applied_by = #{by}, applied_wo_cnt = #{woCnt},
                    applied_op_cnt = #{opCnt}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where plan_id = #{id} and status = 'CALCULATED' and row_ver = #{rowVer}

mapper.select:
select o.plan_op_id, o.wo_id, o.op_seq, o.node_id, p.equip_id as cur_equip_id
  from aps_plan_op o join prd_wo_proc p on p.wo_id = o.wo_id and p.op_seq = o.op_seq
 where o.plan_id = #{planId}

mapper.update:
update aps_pin set res_kind = #{kind}, equip_id = #{equipId}, node_id = #{nodeId}, start_at = #{startAt},
                   row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where pin_id = #{id} and use_yn = 'Y' and row_ver = #{rowVer}

mapper.sql:
 from aps_plan a join sys_plant p on p.comp_cd = a.comp_cd and p.plant_cd = a.plant_cd
where a.calculated_at >= #{c.from} and a.calculated_at < #{c.to}
  and a.plant_cd = #{c.plantCd}

mapper.select:
select 

 order by a.calculated_at desc, a.plan_id desc
 limit #{limit}

select 
  from aps_plan a join sys_plant p on p.comp_cd = a.comp_cd and p.plant_cd = a.plant_cd
 where a.plan_id = #{id}
